mapper.select:
select ETR_ENTRUST.ENTRUST_STATUS as entrustStatus, ETR_ENTRUST.ENTRUST_ID as entrustId, ETR_ENTRUST.PORTFOLIO_ID as portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME as portfolioName, ETR_ENTRUST_ADD.ASSET_TYPE1 as assetType, ETR_ENTRUST_ADD.EXC_DEAL_TYPE as tradeType, ETR_ENTRUST_ADD.CUR_PAIR as ccyPair, ETR_ENTRUST.PS as tradePs, ETR_ENTRUST_ADD.EXC_FXS_TERM_TYPE as termType, to_char(ETR_ENTRUST_ADD.VDATE,'yyyy-MM-dd') || ' - ' || to_char(ETR_ENTRUST_ADD.VDATE2,'yyyy-MM-dd') as proximalDeliveryDate , to_char(ETR_ENTRUST_ADD.MDATE,'yyyy-MM-dd') || ' - ' || to_char(ETR_ENTRUST_ADD.MDATE2,'yyyy-MM-dd') as remoteDeliveryDate , ETR_ENTRUST.PRICE as swapsPoint, ETR_ENTRUST.CCY as tradeCcy, ETR_ENTRUST.VDATE as vdate, ETR_ENTRUST.MDATE as mdate, ETR_ENTRUST.ENTRUST_AMT as tradeAmt, ETR_ENTRUST_ADD.COR_CCY as contraCcy, A.FINISH_AMT as completeAmt, NVL2(A.FINISH_AMT ,ROUND(A.FINISH_AMT/ETR_ENTRUST.ENTRUST_AMT,4),0) as tradePercent, ETR_ENTRUST.REMARK as remark from ETR_ENTRUST left join PTL_PORTFOLIO on PTL_PORTFOLIO.PORTFOLIO_ID=ETR_ENTRUST.PORTFOLIO_ID inner join ETR_ENTRUST_ADD on ETR_ENTRUST_ADD.ENTRUST_ID=ETR_ENTRUST.ENTRUST_ID left join (select ENTRUST_ID,sum(FINISH_AMT) as FINISH_AMT from ETR_FINISH_STATUS group by ENTRUST_ID)A on A.ENTRUST_ID=ETR_ENTRUST.ENTRUST_ID inner join PTL_PORTFOLIO_AUTHORITY on PTL_PORTFOLIO_AUTHORITY.USER_ID=#{userId} AND PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID=ETR_ENTRUST.PORTFOLIO_ID
AND (PTL_PORTFOLIO.PORTFOLIO_ID IN
null) OR PTL_PORTFOLIO.PORTFOLIO_ID IN (
#{prot}
or PTL_PORTFOLIO.PARENT_PORTFOLIO_ID IN
null) OR PTL_PORTFOLIO.PARENT_PORTFOLIO_ID IN (
#{prot}
)
AND ETR_ENTRUST_ADD.EXC_DEAL_TYPE IN
#{item}
AND ETR_ENTRUST_ADD.CUR_PAIR IN
#{item}
AND ETR_ENTRUST_ADD.EXC_FXS_TERM_TYPE IN
#{item}
AND ETR_ENTRUST.PS IN
#{item}
AND ETR_ENTRUST.ENTRUST_STATUS IN
#{item}
AND ETR_ENTRUST.VDATE >=to_date(#{startDate},'yyyy-MM-dd')
AND ETR_ENTRUST.MDATE <=to_date(#{endDate},'yyyy-MM-dd')
AND ETR_ENTRUST.FINPROD_TYPE2 =#{F13}
order by ETR_ENTRUST.ENTRUST_ID DESC
